insert into consumables_import_settings values(20);
do $$
declare s record; e public.consumables; item_id uuid; code text; prefix text; next_number bigint;
 inserted integer:=0; matched integer:=0; key text;
begin
 for s in select * from consumables_import_source order by item_code loop
  key:='catalog-20261022:'||s.item_code;
  if exists(select 1 from public.consumables where catalog_key=key and archived_at is not null) then
    raise exception 'Catalog identity % is archived. Review and explicitly restore it; do not reimport it.',key;
  end if;
  -- Even an exact match does not resolve another legacy generic candidate.
  if exists(select 1 from public.consumables c where c.archived_at is null and
    (mcpa_auth_private.consumable_normalize(c.name)=mcpa_auth_private.consumable_normalize(s.name)
      or starts_with(mcpa_auth_private.consumable_normalize(c.name),mcpa_auth_private.consumable_normalize(s.name)||' ')
      or (mcpa_auth_private.consumable_normalize(c.name)='cutting disc' and s.name='Metal Cutting Disc'))
    and (mcpa_auth_private.consumable_normalize(c.name)<>mcpa_auth_private.consumable_normalize(s.name)
      or not exists(select 1 from consumables_import_source v where v.name=s.name and mcpa_auth_private.consumable_normalize(v.specification)=mcpa_auth_private.consumable_normalize(c.specification))
      or (mcpa_auth_private.consumable_normalize(c.specification)=mcpa_auth_private.consumable_normalize(s.specification)
        and mcpa_auth_private.consumable_unit(c.unit)<>mcpa_auth_private.consumable_unit(s.unit)))) then
    raise exception 'Reconcile existing name/specification/unit for % before importing. No stock changed.',s.name;
  end if;
  select * into e from public.consumables c where c.archived_at is null and (c.catalog_key=key or
    (mcpa_auth_private.consumable_normalize(c.name)=mcpa_auth_private.consumable_normalize(s.name)
      and mcpa_auth_private.consumable_normalize(c.specification)=mcpa_auth_private.consumable_normalize(s.specification)
      and mcpa_auth_private.consumable_unit(c.unit)=mcpa_auth_private.consumable_unit(s.unit))) for update;
  if found then
    if mcpa_auth_private.consumable_normalize(e.name)<>mcpa_auth_private.consumable_normalize(s.name)
      or mcpa_auth_private.consumable_normalize(e.specification)<>mcpa_auth_private.consumable_normalize(s.specification)
      or mcpa_auth_private.consumable_unit(e.unit)<>mcpa_auth_private.consumable_unit(s.unit)
      or (e.category is not null and e.category<>s.category) or (e.catalog_key is not null and e.catalog_key<>key) then
      raise exception 'Existing catalog identity/category changed for %. Review manually.',s.item_code;
    end if;
    item_id:=e.id; matched:=matched+1; code:=e.item_code;
  else item_id:=gen_random_uuid(); code:=null;end if;
  if code is null then
    code:=s.item_code;
    if exists(select 1 from public.consumables where item_code=code) then
      prefix:=split_part(s.item_code,'-',1);
      select greatest(coalesce(max(substring(item_code from '[0-9]+$')::bigint),0),
        (select max(substring(item_code from '[0-9]+$')::bigint) from consumables_import_source where item_code like prefix||'-%'))+1
        into next_number from public.consumables where item_code like prefix||'-%';
      code:=prefix||'-'||case when next_number<1000 then lpad(next_number::text,3,'0') else next_number::text end;
    end if;
  end if;
  if e.id is not null then
    if e.catalog_key is null or e.category is null or e.item_code is null then
      update public.consumables set category=s.category,item_code=code,catalog_key=key,version=version+1,updated_at=clock_timestamp() where id=item_id;
    end if;
  else
    insert into public.consumables(id,name,unit,specification,category,item_code,catalog_key,current_stock,minimum_stock)
      select item_id,s.name,s.unit,s.specification,s.category,code,key,100,minimum from consumables_import_settings;
    insert into public.consumable_stock_movements(id,consumable_id,kind,quantity_change,balance_after,note)
      select item_id,item_id,'opening',100,100,'Catalog import 2026-10-22: '||s.item_code from consumables_import_settings;
    inserted:=inserted+1;
  end if;
 end loop;
 raise notice 'Catalog imported: % inserted, % existing matches preserved.',inserted,matched;
end $$;
